#include <Rcpp.h>
#include <libcoherentSurv/causal_target.hpp>
// [[Rcpp::export]]
Rcpp::List cs_cpp_causal_target(Rcpp::NumericVector rates,Rcpp::NumericVector censor,Rcpp::NumericVector propensity,Rcpp::IntegerMatrix next_state,Rcpp::IntegerVector subject_group,Rcpp::NumericMatrix records,int bins,double horizon,int maxit,double tolerance){
 const std::size_t S=static_cast<std::size_t>(next_state.nrow()),M=static_cast<std::size_t>(next_state.ncol()),D=M+1;std::vector<std::size_t> nxt(S*M),groups(subject_group.size());
 for(std::size_t q=0;q<S;++q){for(std::size_t k=0;k<M;++k){const int z=next_state(static_cast<int>(q),static_cast<int>(k));if(z<0)Rcpp::stop("negative state index");nxt[q*M+k]=static_cast<std::size_t>(z);}}for(R_xlen_t i=0;i<subject_group.size();++i){if(subject_group[i]<0)Rcpp::stop("negative nuisance group");groups[static_cast<std::size_t>(i)]=static_cast<std::size_t>(subject_group[i]);}
 std::vector<coherentSurv::CTRecord> rows;for(int i=0;i<records.nrow();++i){if(records.ncol()!=6||records(i,0)<0||records(i,1)<0||records(i,2)<0)Rcpp::stop("invalid continuous row schema");rows.push_back({static_cast<std::size_t>(records(i,0)),static_cast<std::size_t>(records(i,1)),static_cast<std::size_t>(records(i,2)),records(i,3),records(i,4),static_cast<int>(records(i,5))});}
 coherentSurv::CausalContinuousTarget engine(static_cast<std::size_t>(censor.size()),static_cast<std::size_t>(bins),S,M,horizon,nxt,groups,rows,Rcpp::as<std::vector<double>>(censor),Rcpp::as<std::vector<double>>(propensity));const auto z=engine.fit(Rcpp::as<std::vector<double>>(rates),maxit,tolerance);
 Rcpp::NumericMatrix eif(subject_group.size(),static_cast<int>(D)),cov(static_cast<int>(D),static_cast<int>(D));for(R_xlen_t i=0;i<subject_group.size();++i)for(std::size_t j=0;j<D;++j)eif(i,static_cast<int>(j))=z.eif[static_cast<std::size_t>(i)*D+j];for(std::size_t j=0;j<D;++j)for(std::size_t k=0;k<D;++k)cov(static_cast<int>(j),static_cast<int>(k))=z.covariance[j*D+k];
 return Rcpp::List::create(Rcpp::Named("estimate")=z.estimate,Rcpp::Named("initial")=z.initial,Rcpp::Named("EIF")=eif,Rcpp::Named("covariance")=cov,Rcpp::Named("se")=z.se,Rcpp::Named("rates")=z.rates,Rcpp::Named("values")=z.values,Rcpp::Named("polynomial")=z.polynomial,Rcpp::Named("score")=z.score,Rcpp::Named("score_trace")=z.score_trace,Rcpp::Named("iterations")=z.iterations,Rcpp::Named("converged")=z.converged,Rcpp::Named("interpolation_error")=z.interpolation_error);
}
